function integrationsPage(){if(!IntegrationHub.isUnlocked())return integrationLockPage();return integrationsUnlockedPage()}
function integrationLockPage(){return `<div class="panel" style="max-width:620px;margin:70px auto;text-align:center;padding:42px"><div style="font-size:48px">🔐</div><div class="kicker">PROTECTED AREA</div><h2>Integration Control Center</h2><p class="muted">This area contains payment, courier, messaging and business-service credentials. Enter the integration panel password to continue.</p><div class="field" style="text-align:left"><label>Integration panel password</label><input id="integrationPass" type="password" inputmode="numeric" placeholder="Enter password" autocomplete="off"></div><button class="btn primary" style="width:100%" onclick="unlockIntegrations()">Unlock Integration Panel</button><p class="muted" style="font-size:12px;margin-top:12px">Live credentials are added only after deployment.</p></div>`}
async function unlockIntegrations(){const p=document.getElementById("integrationPass")?.value||"";const r=await IntegrationHub.unlockPanel(p).catch(()=>({ok:false,error:"Backend unavailable"}));if(!r.ok)return toast(r.error||"Invalid password");toast("Integration panel unlocked");render()}
function integrationsUnlockedPage(){
 if(sessionStorage.getItem('npt_integrations_unlocked')!=='1'){
  return `<div class="lock-screen"><div class="lock-icon">🔒</div><h3>Integrations panel is locked</h3><p>Enter the access code to view and manage connected services, API keys and webhooks.</p><input id="integrationsPass" type="password" inputmode="numeric" maxlength="6" placeholder="••••••" onkeydown="if(event.key==='Enter')unlockIntegrations()" autofocus><div class="lock-error" id="lockError"></div><button class="btn primary" style="width:100%" onclick="unlockIntegrations()">Unlock</button></div>`;
 }
 return integrationsPageContent();
}
async function unlockIntegrations(){
 const v=document.getElementById('integrationsPass')?.value||document.getElementById('integrationPass')?.value||'';
 const r=await IntegrationHub.unlockPanel(v).catch(()=>({ok:false,error:'Backend unavailable'}));
 if(r.ok){sessionStorage.setItem('npt_integrations_unlocked','1');go('integrations')}
 else{const e=document.getElementById('lockError');if(e)e.textContent=r.error||'Incorrect access code. Try again.';const i=document.getElementById('integrationsPass');if(i)i.value=''}
}
function integrationsPageContent(){
 const h=IntegrationHub.state(), cs=IntegrationHub.connectors;
 const phases=[[1,'Core Commerce','Database, identity, realtime and media'],[2,'Payments','Checkout, verification, refunds and webhooks'],[3,'Delivery','Courier booking, AWB and live tracking'],[4,'Communication','WhatsApp, email, SMS and push notifications'],[5,'Growth & Experience','Invoices, analytics, shopping feeds and support'],[6,'Advanced Operations','Maps, reviews, search, suppliers, accounting, marketing, security, CRM and warehouses']];
 const configured=window._serverInt||{};
 const cards=phases.map(([num,title,desc])=>{let list=cs.filter(c=>c.phase===num),ready=list.filter(c=>h.enabled[c.id]||configured[c.id]).length;return `<section class="integration-phase"><div class="phase-head"><div><span class="phase-num">0${num}</span><div><div class="kicker">PHASE ${num}</div><h3>${title}</h3><p>${desc}</p></div></div><span class="phase-progress">${ready}/${list.length} configured</span></div><div class="integration-cards">${list.map(c=>{let live=!!configured[c.id],demo=!!h.enabled[c.id];return `<div class="integration-card ${live?'ready':''}"><div class="integration-icon">${c.icon}</div><div class="integration-main"><div class="integration-title"><b>${c.name}</b><span class="int-status ${live?'ok':'demo'}">${live?'CONNECTED':demo?'DEMO':'NOT SET'}</span></div><p>${c.desc}</p><div class="event-pills">${c.events.map(e=>`<span>${e}</span>`).join('')}</div><div class="integration-actions"><button class="btn primary" onclick="apiConfig('${c.id}')">API / Credentials</button><button class="btn ghost" onclick="testIntegration('${c.id}')">Test</button><button class="btn ghost" onclick="integrationInfo('${c.id}')">Details</button></div></div></div>`}).join('')}</div></section>`}).join('');
 const logs=h.logs.slice(0,8).map(x=>`<div class="log-row"><span class="log-dot"></span><div><b>${x.connector?('Connector test · '+(IntegrationHub.connector(x.connector)?.name||x.connector)):x.event}</b><small>${new Date(x.time).toLocaleString()} · ${x.mode}</small></div><span class="badge green">OK</span></div>`).join('')||'<div class="empty">No local events yet.</div>';
 return `<div class="integration-hero"><div><div class="kicker">INTEGRATION CONTROL CENTER</div><h1>Connect once. Run the whole store.</h1><p>Configure provider credentials here. The customer store and admin use the same backend contract, so the client can change provider keys without editing the storefront code.</p><div class="hero-chips"><span>${cs.length} modules</span><span>API Center</span><span>Server-side secrets</span><span>Webhook-ready</span></div></div><div class="mode-box"><small>Environment</small><div class="mode-toggle"><button class="${h.mode==='demo'?'active':''}" onclick="setIntegrationMode('demo')">Demo</button><button class="${h.mode==='production'?'active':''}" onclick="setIntegrationMode('production')">Production</button></div><p>${h.mode==='production'?'Live credentials are read by the backend.':'Demo mode never sends real money, messages or shipments.'}</p></div></div>
 <div class="integration-summary"><div><b>${cs.length}</b><span>Modules</span></div><div><b>${Object.values(configured).filter(Boolean).length}</b><span>Server configured</span></div><div><b>${Object.values(IntegrationHub.providers).flat().length}</b><span>Provider choices</span></div><div><b>${h.logs.length}</b><span>Local events</span></div></div>
 <div class="panel api-banner"><div><div class="kicker">CLIENT-FRIENDLY API CENTER</div><h3>Change credentials without touching the code</h3><p>Choose an integration below, select the provider, paste the credentials, save, then run Test. Secrets are sent to the backend and are never displayed back in full.</p></div><button class="btn primary" onclick="apiConfig('payment')">Open API Center</button></div>
 <div class="integration-layout"><div>${cards}</div><aside class="integration-side"><div class="panel sticky-panel"><div class="toolbar"><h3 style="margin:0">Provider options</h3><span class="badge blue">Server-side</span></div>${Object.entries(IntegrationHub.providers).map(([k,v])=>`<div class="provider-row"><span>${k}</span><b>${v.join(' · ')}</b></div>`).join('')}<div class="secure-note"><b>🔐 Credentials never belong in customer JavaScript</b><p>Use API Center to send them to the backend. Production payment, courier and messaging calls must execute server-side.</p></div></div><div class="panel" style="margin-top:14px"><div class="toolbar"><h3 style="margin:0">Event stream</h3><button class="btn ghost" onclick="clearIntegrationLogs()">Clear</button></div>${logs}</div></aside></div>`;
}
async function refreshServerIntegrations(){const r=await IntegrationHub.serverStatus();window._serverInt=r.configured||{};return r}
async function syncServerStore(){
 if(sessionStorage.getItem("npt_admin")!=="1")return false;
 try{
  const token=sessionStorage.getItem("npt_admin_token")||"";
  const r=await fetch((window.NPT_API_BASE||"")+"/api/store/state",{headers:{authorization:"Bearer "+token},cache:"no-store"});
  const d=await r.json();
  if(!d.ok)throw new Error(d.error||"Store sync failed");
  if(Array.isArray(d.products))A.products=d.products;
  lastAdminSyncAt=Date.now();
  updateLiveSyncUI();
  return true;
 }catch(e){return false}
}
let liveSyncEnabled=sessionStorage.getItem('npt_admin_live_sync')!=='0';let liveSyncTimer=null,liveCatalogTimer=null,liveSyncBusy=false,lastAdminSyncAt=0;
function formatSyncAge(){if(!lastAdminSyncAt)return 'not synced yet';const sec=Math.max(0,Math.floor((Date.now()-lastAdminSyncAt)/1000));if(sec<2)return 'just now';if(sec<60)return `${sec}s ago`;return `${Math.floor(sec/60)}m ago`}
function updateLiveSyncUI(){const status=document.querySelector('.live-sync-status');const strip=document.querySelector('.live-sync-strip');const toggle=document.querySelector('.sync-toggle');const label=document.getElementById('liveSyncLabel');const meta=document.getElementById('liveSyncMeta');const last=document.getElementById('lastSyncText');if(status)status.className=`live-sync-status ${liveSyncEnabled?'is-on':'is-off'}`;if(strip)strip.className=`live-sync-strip ${liveSyncEnabled?'on':'off'}`;if(toggle){toggle.className=`sync-toggle ${liveSyncEnabled?'on':'off'}`;toggle.setAttribute('aria-pressed',String(liveSyncEnabled));const b=toggle.querySelector('b');if(b)b.textContent=liveSyncEnabled?'ON':'OFF'}if(label)label.textContent=liveSyncEnabled?'Live sync ON':'Live sync OFF';if(meta)meta.textContent=liveSyncEnabled?`Auto-updates · ${formatSyncAge()}`:'Updates paused';if(last)last.textContent=lastAdminSyncAt?`Last synced ${formatSyncAge()}`:'Waiting for first sync…'}
function toggleLiveSync(){liveSyncEnabled=!liveSyncEnabled;sessionStorage.setItem('npt_admin_live_sync',liveSyncEnabled?'1':'0');if(liveSyncEnabled){startLiveSync();syncLiveAdmin(true)}else stopLiveSync();updateLiveSyncUI();toast(liveSyncEnabled?'Live order sync enabled':'Live order sync paused')}
function startLiveSync(){if(liveSyncTimer)clearInterval(liveSyncTimer);if(liveCatalogTimer)clearInterval(liveCatalogTimer);if(!liveSyncEnabled)return;syncLiveAdmin(true);liveSyncTimer=setInterval(()=>syncLiveAdmin(false),3000);liveCatalogTimer=setInterval(()=>syncServerStore().then(()=>{if(page==='products'){const t=document.getElementById('ptable');if(t)t.innerHTML=productTable(A.products)}}),8000)}
function stopLiveSync(){if(liveSyncTimer){clearInterval(liveSyncTimer);liveSyncTimer=null}if(liveCatalogTimer){clearInterval(liveCatalogTimer);liveCatalogTimer=null}}
async function syncLiveAdmin(force=false){if(!liveSyncEnabled||sessionStorage.getItem('npt_admin')!=='1'||liveSyncBusy)return false;liveSyncBusy=true;try{const token=sessionStorage.getItem('npt_admin_token')||'';const r=await fetch((window.NPT_API_BASE||'')+'/api/store/orders',{headers:{authorization:'Bearer '+token},cache:'no-store'});const d=await r.json();if(!d.ok)throw new Error(d.error||'Sync failed');const before=JSON.stringify({o:A.orders.map(x=>x.id+':'+x.status+':'+(x.awb||'')+':'+x.total),n:A.notifications.map(x=>x.id+':'+x.read),c:A.customers.map(x=>x.mobile||x.email)});A.orders=d.orders||[];A.customers=d.customers||[];A.notifications=d.notifications||[];const after=JSON.stringify({o:A.orders.map(x=>x.id+':'+x.status+':'+(x.awb||'')+':'+x.total),n:A.notifications.map(x=>x.id+':'+x.read),c:A.customers.map(x=>x.mobile||x.email)});lastAdminSyncAt=Date.now();if(before!==after||force){updateAdminNotificationBadge();const table=document.getElementById('otable');if(page==='orders'&&table&&!document.activeElement?.classList.contains('searchbox')){table.innerHTML=ordersTable(orderStatusFilter?A.orders.filter(o=>o.status===orderStatusFilter):A.orders);table.classList.remove('live-updated');void table.offsetWidth;table.classList.add('live-updated')}if(page==='dashboard'){const ordersStat=document.querySelector('[data-live-stat="orders"]');const revenueStat=document.querySelector('[data-live-stat="revenue"]');const customerStat=document.querySelector('[data-live-stat="customers"]');const lowStat=document.querySelector('[data-live-stat="low"]');if(ordersStat)ordersStat.textContent=A.orders.length+156;if(revenueStat)revenueStat.textContent=NPT.money(A.orders.reduce((a,o)=>a+o.total,0)+248750);if(customerStat)customerStat.textContent=A.customers.length+425;if(lowStat)lowStat.textContent=A.products.filter(p=>p.stock<=5).length}const openModal=document.getElementById('modal');const orderId=openModal?.dataset?.orderId;if(openModal&&orderId){const fresh=A.orders.find(o=>o.id===orderId);if(fresh)refreshOpenOrderModal(fresh)}toast('Live order data synced')}updateLiveSyncUI();save();return true}catch(e){updateLiveSyncUI();return false}finally{liveSyncBusy=false}}
function refreshOpenOrderModal(o){const s=document.getElementById('os');const ps=document.getElementById('ops');const c=document.getElementById('oc');const aw=document.getElementById('oawb');const tr=document.getElementById('otrack');if(s)s.value=o.status||'Order Placed';if(ps)ps.value=o.paymentStatus||'Paid';if(c)c.value=o.courier||'Pending';if(aw)aw.value=o.awb||'';if(tr)tr.value=o.trackingUrl||'';const title=document.querySelector('#modal .modalhead h3');if(title)title.textContent=o.id;const live=document.getElementById('modalLiveStatus');if(live){live.textContent=`Live synced · ${new Date().toLocaleTimeString()}`;live.classList.remove('flash');void live.offsetWidth;live.classList.add('flash')}}
if(liveSyncEnabled)startLiveSync();
async function apiConfig(id){const c=IntegrationHub.connector(id);if(!c)return;const fields={supabase:['SUPABASE_URL','SUPABASE_PUBLISHABLE_KEY','SUPABASE_SERVICE_ROLE_KEY'],payment:['RAZORPAY_KEY_ID','RAZORPAY_KEY_SECRET','RAZORPAY_WEBHOOK_SECRET'],courier:['COURIER_PROVIDER','COURIER_API_KEY','COURIER_API_SECRET'],whatsapp:['WHATSAPP_ACCESS_TOKEN','WHATSAPP_PHONE_NUMBER_ID'],email:['EMAIL_PROVIDER','EMAIL_API_KEY','SMTP_HOST','SMTP_USER','SMTP_PASSWORD'],sms:['SMS_PROVIDER','SMS_API_KEY'],push:['FIREBASE_PROJECT_ID','FIREBASE_CLIENT_EMAIL','FIREBASE_PRIVATE_KEY','FIREBASE_WEB_API_KEY','FIREBASE_MESSAGING_SENDER_ID','FIREBASE_APP_ID','FIREBASE_VAPID_KEY'],maps:['GOOGLE_MAPS_API_KEY'],accounting:['ACCOUNTING_PROVIDER','ACCOUNTING_API_KEY'],catalog:['WHATSAPP_CATALOG_ID'],meta:['META_PIXEL_ID','META_ACCESS_TOKEN'],googleads:['GOOGLE_ADS_ID','GOOGLE_ADS_CONVERSION_ID'],security:['SENTRY_DSN'],crm:['CRM_PROVIDER','CRM_API_KEY'],support:['SUPPORT_PROVIDER','SUPPORT_API_KEY'],warehouse:['WAREHOUSE_API_URL','WAREHOUSE_API_KEY'],merchant:['GOOGLE_MERCHANT_ID'],analytics:['GOOGLE_ANALYTICS_ID'],auth:['AUTH_PROVIDER','AUTH_API_KEY'],realtime:['REALTIME_URL','REALTIME_API_KEY'],storage:['STORAGE_URL','STORAGE_API_KEY'],webhooks:['PAYMENT_WEBHOOK_SECRET'],tracking:['COURIER_TRACKING_API_KEY'],invoice:['INVOICE_PROVIDER','INVOICE_API_KEY'],reviews:['REVIEWS_PROVIDER','REVIEWS_API_KEY'],search:['SEARCH_PROVIDER','SEARCH_API_KEY'],supplier:['SUPPLIER_API_URL','SUPPLIER_API_KEY'],abandoned:['MESSAGING_RECOVERY_API_KEY'],'live-support':['LIVE_SUPPORT_API_URL','LIVE_SUPPORT_API_KEY']};
 const keys=fields[id]||[];document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div class="modalbox api-modal"><div class="modalhead"><div><div class="kicker">API CENTER</div><h3>${c.name}</h3><p class="muted">${c.desc}</p></div><button class="btn ghost" onclick="closeModal()">×</button></div><div class="notice"><b>Secure configuration</b><br>Enter credentials here. Values are submitted to the server and are not stored in browser localStorage.</div><div class="field"><label>Provider / service</label><input id="api_provider" placeholder="e.g. Razorpay, Shiprocket, Supabase"></div>${keys.map(k=>`<div class="field"><label>${k.replaceAll('_',' ')}</label><input id="api_${k}" type="password" autocomplete="off" placeholder="Paste ${k}"></div>`).join('')}<div class="api-modal-actions"><button class="btn ghost" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveApiConfig('${id}',${JSON.stringify(keys).replaceAll('"','&quot;')})">Save & Test</button></div></div></div>`)}
async function saveApiConfig(id,keys){const values={};const provider=document.getElementById('api_provider')?.value.trim();const providerKey={payment:'PAYMENT_PROVIDER',courier:'COURIER_PROVIDER',email:'EMAIL_PROVIDER',sms:'SMS_PROVIDER',accounting:'ACCOUNTING_PROVIDER',crm:'CRM_PROVIDER',support:'SUPPORT_PROVIDER',search:'SEARCH_PROVIDER',reviews:'REVIEWS_PROVIDER',invoice:'INVOICE_PROVIDER'}[id];if(provider&&providerKey)values[providerKey]=provider;keys.forEach(k=>{const el=document.getElementById('api_'+k);if(el&&el.value.trim())values[k]=el.value.trim()});if(!Object.keys(values).length)return toast('Enter at least one credential');const r=await IntegrationHub.saveCredentials(id,values);if(!r.ok)return toast(r.error||'Could not save credentials');await IntegrationHub.testServer(id);await refreshServerIntegrations();closeModal();toast(caps(id)+' connected on server');render()}
function caps(id){return IntegrationHub.connector(id)?.name||id}
async function testIntegration(id){const server=await IntegrationHub.testServer(id).catch(()=>({ok:false}));IntegrationHub.test(id);toast(server.configured?'Server configuration found':'Demo connector passed');await refreshServerIntegrations();render()}
function setIntegrationMode(mode){IntegrationHub.setMode(mode);toast('Environment switched to '+mode);render()}
function clearIntegrationLogs(){let s=IntegrationHub.state();s.logs=[];localStorage.setItem('npt_integration_hub_v1',JSON.stringify(s));render()}
function integrationInfo(id){let c=IntegrationHub.connector(id);if(!c)return;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div class="modalbox integration-detail"><div class="modalhead"><div><div class="kicker">INTEGRATION MODULE</div><h3>${c.name}</h3></div><button class="btn ghost" onclick="closeModal()">×</button></div><p>${c.desc}</p><div class="detail-grid"><div><small>Phase</small><b>${c.phase}</b></div><div><small>Group</small><b>${c.group}</b></div><div><small>Events</small><b>${c.events.length}</b></div></div><h4>Supported events</h4><div class="event-pills">${c.events.map(e=>`<span>${e}</span>`).join('')}</div><div class="notice" style="margin-top:18px">Use API / Credentials to configure the service. The browser never needs the provider secret.</div></div></div>`)}
function notificationsPage(){return `<div class="notification-workspace"><div class="panel notification-compose"><div class="toolbar"><div><div class="kicker">CUSTOMER COMMUNICATIONS</div><h3 style="margin:2px 0 4px">Send an alert or offer</h3><p class="muted">Create one message and deliver it through the channels you have configured.</p></div><span class="badge blue">${A.customers.length} customers</span></div><div class="field"><label>Audience</label><select id="ntarget" onchange="toggleNotificationTarget(this.value)"><option value="all">All customers</option><option value="frequent">Frequent orderers · 3+</option><option value="recent">Ordered in last 30 days</option><option value="highvalue">High value · ₹10,000+</option><option value="ordered">Customers who have ordered</option><option value="never">Never ordered</option><option value="specific">Specific customer</option></select></div><div id="specificTarget" class="specific-target" style="display:none"><div class="field"><label>Customer mobile</label><input id="nmobile" inputmode="tel" placeholder="10-digit mobile"></div><div class="field"><label>Customer email</label><input id="nemail" type="email" placeholder="customer@email.com"></div></div><div class="field"><label>Message type</label><select id="ntype"><option value="general">General update</option><option value="offer">Offer</option><option value="promotion">Promotion</option><option value="order">Order update</option></select></div><div class="field"><label>Title</label><input id="ntitle" maxlength="80" placeholder="Weekend Power Tool Offer"></div><div class="field"><label>Message</label><textarea id="ntext" rows="5" maxlength="240" placeholder="Tell customers about your offer or update."></textarea></div><div class="field"><label>Offer / coupon code <span class="muted">optional</span></label><input id="noffer" placeholder="POWER10"></div><div class="channel-picker"><label>Delivery channels</label><div class="channel-grid"><label><input type="checkbox" id="chInapp" checked> <span>In-store</span><small>Notification bell</small></label><label><input type="checkbox" id="chPush" checked> <span>Chrome push</span><small>Browser permission</small></label><label><input type="checkbox" id="chEmail"> <span>Email</span><small>Configured email provider</small></label><label><input type="checkbox" id="chSms"> <span>SMS</span><small>Configured SMS provider</small></label><label><input type="checkbox" id="chWa"> <span>WhatsApp</span><small>Business Cloud API</small></label></div></div><div id="notificationResult" class="notification-result" aria-live="polite"></div><button class="btn primary send-notification-btn" onclick="sendAdminNotification()">Send notification</button></div><div class="panel notification-preview"><div class="kicker">CUSTOMER PREVIEW</div><div class="push-preview"><div class="push-brand"><span class="push-dot">NP</span><span><b>New Pratap Tools</b><small>now</small></span></div><h4 id="previewTitle">Your notification title</h4><p id="previewText">Your customer message will appear here.</p></div><div class="notification-channel-list"><h4>Available channels</h4><div>🔔 <b>Notification center</b><span>Always available when stored.</span></div><div>◉ <b>Chrome notification</b><span>Requires customer permission.</span></div><div>✉ <b>Email</b><span>Requires email provider credentials.</span></div><div>SMS <b>Phone message</b><span>Requires SMS provider credentials.</span></div><div>WA <b>WhatsApp</b><span>Requires WhatsApp credentials/templates.</span></div></div></div></div>`}
function toggleNotificationTarget(v){const el=document.getElementById('specificTarget');if(el)el.style.display=v==='specific'?'grid':'none'}

async function sendAdminNotification(){const target=document.getElementById('ntarget')?.value||'all',channels=[];if(document.getElementById('chInapp')?.checked)channels.push('inapp');if(document.getElementById('chPush')?.checked)channels.push('push');if(document.getElementById('chEmail')?.checked)channels.push('email');if(document.getElementById('chSms')?.checked)channels.push('sms');if(document.getElementById('chWa')?.checked)channels.push('whatsapp');const b={audience:target,mobile:document.getElementById('nmobile')?.value||'',email:document.getElementById('nemail')?.value||'',type:document.getElementById('ntype')?.value||'general',title:document.getElementById('ntitle')?.value||'',text:document.getElementById('ntext')?.value||'',offerCode:document.getElementById('noffer')?.value||'',channels};if(!b.title.trim())return showNotificationResult('Add a notification title.','error');if(!b.text.trim())return showNotificationResult('Add a message before sending.','error');if(!channels.length)return showNotificationResult('Select at least one delivery channel.','error');const token=sessionStorage.getItem('npt_admin_token')||'';const btn=document.querySelector('.send-notification-btn');if(btn){btn.disabled=true;btn.textContent='Sending…'}try{const r=await fetch((window.NPT_API_BASE||'')+'/api/admin/notifications/send',{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+token},body:JSON.stringify(b)});const d=await r.json();if(!d.ok)throw new Error(d.error||'Notification could not be sent');const parts=[];if(d.count)parts.push(`${d.count} customer${d.count===1?'':'s'} targeted`);if(d.deliveries?.push)parts.push(`Chrome/FCM ${d.deliveries.push.sent||0} delivered`);if(d.deliveries?.email)parts.push(`email ${d.deliveries.email.sent||0} sent`);if(d.deliveries?.sms)parts.push(`SMS ${d.deliveries.sms.sent||0} sent`);if(d.deliveries?.whatsapp)parts.push(`WhatsApp ${d.deliveries.whatsapp.sent||0} sent`);showNotificationResult('✓ '+(parts.join(' · ')||d.message||'Notification processed.'),'success');syncLiveAdmin(true)}catch(e){showNotificationResult(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent='Send notification'}}}

function showNotificationResult(text,type){const el=document.getElementById('notificationResult');if(el){el.className='notification-result '+type;el.textContent=text}}
function notificationPreviewBind(){const t=document.getElementById('ntitle'),m=document.getElementById('ntext');if(t)t.oninput=()=>{const x=document.getElementById('previewTitle');if(x)x.textContent=t.value||'Your notification title'};if(m)m.oninput=()=>{const x=document.getElementById('previewText');if(x)x.textContent=m.value||'Your customer message will appear here'}}
function settingsPage(){return `<div class="grid2"><div class="panel"><h3>Business settings</h3><div class="field"><label>Business name</label><input value="${NPT.business.name}"></div><div class="field"><label>WhatsApp</label><input value="${NPT.business.phone}"></div><div class="field"><label>Pickup address</label><textarea rows="3">${NPT.business.address}</textarea></div><button class="btn primary" onclick="toast('Settings saved')">Save settings</button></div><div class="panel"><h3>Commerce settings</h3><div class="field"><label>Default shipping charge</label><input value="0"></div><div class="field"><label>Low stock threshold</label><input value="5"></div><div class="field"><label>Tax configuration</label><select><option>Configure later</option><option>GST enabled</option></select></div><button class="btn primary" onclick="toast('Commerce settings saved')">Save settings</button></div></div>`}
function toast(t){let x=document.createElement("div");x.textContent=t;x.style="position:fixed;right:25px;bottom:25px;background:#101828;color:#fff;padding:12px 18px;border-radius:9px;z-index:99";document.body.appendChild(x);setTimeout(()=>x.remove(),1800)}
if(sessionStorage.getItem("npt_admin")==="1"){
 load();
 render();
 Promise.all([syncServerStore(),syncLiveAdmin(true),refreshServerIntegrations()]).finally(()=>{save();render();startLiveSync()});
}else adminLogin();
